Item.method_code:
const { item, itemNode, itemTypeName } = options;
if (!item && !itemNode) {
	return false;
}

const id = item ? item.id : itemNode.getAttribute('id');
const isNew = ArasModules.item.isNew(itemTypeName, id);
if (isNew) {
	return true;
}

const lockedById = item ? item['locked_by_id'] : aras.getItemProperty(itemNode, 'locked_by_id');
if (!lockedById) {
	const lockCommand = commands.commandFactory('LockItem', options);
	const canExecuteLock = lockCommand.canExecute();
	if (!canExecuteLock) {
		const message = lockCommand.getErrorMessage();
		commands.setErrorMessage(message);
		return false;
	}
}

const isLockedByOther = lockedById && lockedById !== aras.user.id;
if (isLockedByOther) {
	return false;
}

const discoverOnly = item ? item['@aras.discover_only'] : itemNode.getAttribute('discover_only');
if (discoverOnly === '1') {
	const message = aras.getResource(
		'',
		'cui.failed.discover_only_item_cannot_be_edit'
	);
	commands.setErrorMessage(message);
	return false;
}

return true;
